/* Invoice Studio — standalone, zero-dependency local-first application */
'use strict';
const KEY='invoice-studio-v1';
const TODAY=()=>new Date().toISOString().slice(0,10);
const uid=()=>globalThis.crypto?.randomUUID?.()||('id_'+Date.now()+'_'+Math.random().toString(36).slice(2));
const round=n=>Math.round((Number(n)||0)*100)/100;
const safeNumber=(value,min=0,max=1e12)=>Math.max(min,Math.min(max,Number(value)||0));
const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const addDays=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const prettyDate=(x)=>x?new Date(x+'T12:00:00').toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'}):'—';
const money=(n,currency)=>{const cur=currency||state.business.currency||'BSD';return new Intl.NumberFormat('en-US',{style:'currency',currency:cur,maximumFractionDigits:2}).format(round(n));};
const iconPaths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',invoice:'<path d="M8 3h8l5 5v13H3V3h5z"/><path d="M15 3v6h6M7 13h10M7 17h7"/>',estimate:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',box:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 10h18M8 6V3h8v3"/>',wallet:'<rect x="2" y="6" width="20" height="15" rx="2"/><path d="M2 10h20M17 15h2M5 6V4h14"/>',chart:'<path d="M3 3v18h18M7 16v-6M12 16V6M17 16v-9"/>',settings:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6l1.5 1.5m9.8 9.8 1.5 1.5M18.4 5.6l-1.5 1.5M7.1 16.9l-1.5 1.5"/><circle cx="12" cy="12" r="5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="M16 16l5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',file:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 13h7M9 17h7"/>',check:'<path d="M4 12l5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',credit:'<rect x="2" y="5" width="20" height="15" rx="2"/><path d="M2 10h20"/>',alert:'<path d="m12 3 10 18H2L12 3zM12 9v4M12 17h.01"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',trash:'<path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14M10 11v7M14 11v7"/>',edit:'<path d="m4 20 4-.8L20 7l-4-4L4 15zM14 5l4 4"/>',send:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',print:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 15h12v7H6zM17 12h2"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',chevron:'<path d="m9 18 6-6-6-6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',more:'<circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>'};
const ico=(n,size=20)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[n]||iconPaths.file}</svg>`;
const blank=()=>({version:1,demo:false,business:{name:'My Business',email:'',phone:'',address:'',taxId:'',logo:'',currency:'BSD',taxLabel:'VAT',taxRate:0,invoicePrefix:'INV',estimatePrefix:'EST',nextInvoice:1001,nextEstimate:1001,website:'',paymentInstructions:'',terms:'Thank you for your business.'},customers:[],items:[],documents:[],expenses:[]});
function sample(){const s=blank();s.demo=true;s.business.name='Seaside Creative Co.';s.business.email='hello@example.com';s.business.address='Nassau, The Bahamas';s.business.paymentInstructions='Bank transfer or cash payment. Contact us for details.';const c1={id:uid(),name:'Oceanview Villas',email:'hello@oceanview.example',phone:'',address:'Nassau, The Bahamas',taxId:''};const c2={id:uid(),name:'Harbour & Co.',email:'accounts@harbour.example',phone:'',address:'Paradise Island, The Bahamas',taxId:''};s.customers=[c1,c2];const i1={id:uid(),name:'Website design',description:'Mobile-first website package',category:'Services',type:'service',price:1200,unit:'project',taxable:false};const i2={id:uid(),name:'Monthly maintenance',description:'Website upkeep and updates',category:'Services',type:'service',price:150,unit:'month',taxable:false};s.items=[i1,i2];let issued=addDays(TODAY(),-11);s.documents=[{id:uid(),kind:'invoice',number:'INV-1001',customerId:c1.id,issued,due:addDays(issued,30),currency:'BSD',lines:[{id:uid(),description:'Website design',qty:1,price:1200,unit:'project',taxable:false}],discount:0,taxRate:0,notes:'Thank you for trusting our team.',status:'sent',payments:[]},{id:uid(),kind:'invoice',number:'INV-1002',customerId:c2.id,issued:addDays(TODAY(),-26),due:addDays(TODAY(),-5),currency:'BSD',lines:[{id:uid(),description:'Brand identity package',qty:1,price:650,unit:'project',taxable:false}],discount:0,taxRate:0,notes:'',status:'sent',payments:[]},{id:uid(),kind:'estimate',number:'EST-1001',customerId:c2.id,issued:TODAY(),due:addDays(TODAY(),14),currency:'BSD',lines:[{id:uid(),description:'Monthly maintenance',qty:3,price:150,unit:'month',taxable:false}],discount:0,taxRate:0,notes:'Valid for 14 days.',status:'sent',payments:[]}];s.business.nextInvoice=1003;s.business.nextEstimate=1002;s.expenses=[{id:uid(),description:'Design software',vendor:'Software vendor',category:'Software',amount:48,date:TODAY(),notes:''}];return s;}
function load(){try{const raw=localStorage.getItem(KEY);if(raw){const val=JSON.parse(raw);if(val&&val.version===1&&Array.isArray(val.documents)&&Array.isArray(val.customers)&&Array.isArray(val.items)&&Array.isArray(val.expenses)&&val.business){return val}}}catch(e){console.error('Cannot load saved data',e)}return sample()}
let state=load();let ui={page:'overview',q:'',filter:'all',modal:null,draft:null,previewId:null,toast:null};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){alert('Storage is full or unavailable. Export your backup now; recent changes may not be saved.');return false}}
if(!localStorage.getItem(KEY))save();
const customer=id=>state.customers.find(x=>x.id===id);
const totals=d=>{const sub=round((d.lines||[]).reduce((a,x)=>a+safeNumber(x.qty)*safeNumber(x.price),0));const disc=round(sub*safeNumber(d.discount,0,100)/100);const taxable=round((d.lines||[]).reduce((a,x)=>a+(x.taxable?safeNumber(x.qty)*safeNumber(x.price):0),0));const vat=round(Math.max(0,taxable-(sub?disc*taxable/sub:0))*safeNumber(d.taxRate,0,100)/100);const total=round(sub-disc+vat);const paid=round((d.payments||[]).reduce((a,p)=>a+safeNumber(p.amount),0));return {sub,disc,vat,total,paid,due:Math.max(0,round(total-paid))}};
const docStatus=d=>{if(d.kind==='estimate')return d.status;if(d.status==='draft')return 'draft';const t=totals(d);if(t.due<.005)return 'paid';if(d.due&&d.due<TODAY())return 'overdue';if(t.paid>0)return 'partial';return 'sent'};
const badge=status=>`<span class="badge badge-${E(status)}">${E(({paid:'Paid',partial:'Part paid',sent:'Sent',draft:'Draft',overdue:'Overdue',accepted:'Accepted',declined:'Declined'})[status]||status)}</span>`;
const docCurrency=d=>d.currency||state.business.currency;
const cMoney=(n,d)=>money(n,docCurrency(d));
const monthKey=(date)=>date?.slice(0,7)||'';
const navItems=[['overview','grid','Overview'],['invoices','invoice','Invoices'],['estimates','estimate','Estimates'],['customers','users','Customers'],['catalog','box','Products & services'],['expenses','wallet','Expenses'],['reports','chart','Reports'],['settings','settings','Settings']];
const pageNames={overview:'Overview',invoices:'Invoices',estimates:'Estimates',customers:'Customers',catalog:'Products & services',expenses:'Expenses',reports:'Reports',settings:'Settings',more:'More'};
function showToast(msg){ui.toast=msg;const old=document.querySelector('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3200)}
function navigate(p){ui.page=p;ui.q='';ui.filter='all';ui.modal=null;render();window.scrollTo(0,0)}
function header(title,description,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">BUSINESS WORKSPACE</div><h1>${E(title)}</h1><p>${E(description)}</p></div><div class="heading-buttons">${buttons}</div></div>`}
function demoBanner(){return state.demo?`<div class="demo-banner"><span><strong>Sample workspace</strong> — These are demonstration records, not your business data.</span><button data-action="clear-demo">Clear samples & set up my business</button></div>`:''}
function shell(){return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${ico('invoice',21)}</span><div><strong>Invoice Studio</strong><small>Business made simple</small></div></div><div class="side-caption">Workspace</div><nav class="nav" aria-label="Main navigation">${navItems.map(([id,symbol,label])=>`<button class="nav-btn ${ui.page===id?'active':''}" data-page="${id}" title="${E(label)}">${ico(symbol)}<span class="nav-label">${E(label)}</span></button>`).join('')}</nav><div class="side-foot"><div class="privacy-note"><span class="dot"></span>Free & private by design.<br>Your records are saved on this device. Back up regularly.</div><div class="side-version">INVOICE STUDIO · V1.0</div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace ${ico('chevron',13)} <strong>${E(pageNames[ui.page])}</strong></div><div class="top-actions"><button class="btn btn-secondary" data-action="backup">${ico('download')} Back up data</button><button class="btn btn-primary" data-action="new-invoice">${ico('plus')} New invoice</button><div class="avatar" aria-label="Workspace">${E((state.business.name||'B').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div></div></header><div class="workspace">${demoBanner()}${renderPage()}</div></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${[['overview','grid','Home'],['invoices','invoice','Invoices'],['estimates','estimate','Estimates'],['more','menu','More']].map(([id,symbol,label])=>`<button class="${ui.page===id||(id==='more'&&!['overview','invoices','estimates'].includes(ui.page))?'active':''}" data-page="${id}">${ico(symbol)}${label}</button>`).join('')}</nav>${renderModal()}<input id="backup-import" type="file" accept="application/json,.json" hidden>`}
function render(){document.getElementById('app').innerHTML=shell();}
const empty=(heading,desc,action,cmd,ic='file')=>`<div class="empty">${ico(ic,38)}<strong>${E(heading)}</strong><p>${E(desc)}</p>${action?`<button class="btn btn-outline" data-action="${cmd}">${ico('plus')}${E(action)}</button>`:''}</div>`;
function metrics(){const bills=state.documents.filter(d=>d.kind==='invoice'&&d.status!=='draft'&&docCurrency(d)===state.business.currency);const values=bills.map(d=>({...totals(d),status:docStatus(d),date:d.issued}));const billed=values.reduce((a,t)=>a+t.total,0);const received=values.reduce((a,t)=>a+t.paid,0);const owing=values.reduce((a,t)=>a+t.due,0);const overdue=values.filter(x=>x.status==='overdue').reduce((a,x)=>a+x.due,0);return [{label:'Total invoiced',value:billed,foot:`${bills.length} issued invoice${bills.length===1?'':'s'}`,ico:'invoice'},{label:'Payments recorded',value:received,foot:'Total entered payments',ico:'credit'},{label:'Outstanding',value:owing,foot:'Unpaid balance',ico:'clock'},{label:'Overdue',value:overdue,foot:'Past due date',ico:'alert'}]}
function renderOverview(){const m=metrics();const foreign=state.documents.filter(d=>d.kind==='invoice'&&docCurrency(d)!==state.business.currency).length;const docs=[...state.documents].sort((a,b)=>b.issued.localeCompare(a.issued)).slice(0,5);return `${header(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}.`,"Here's your business at a glance.",`<button class="btn btn-secondary" data-action="new-estimate">${ico('plus')} New estimate</button><button class="btn btn-primary" data-action="new-invoice">${ico('plus')} Create invoice</button>`)}<div class="metric-grid">${m.map(x=>`<div class="metric"><div class="metric-title"><span>${E(x.label)}</span><span class="metric-icon">${ico(x.ico)}</span></div><div class="metric-value">${money(x.value)}</div><div class="metric-foot">${E(x.foot)}</div></div>`).join('')}</div>${foreign?`<p class="tiny muted" style="margin:-7px 0 20px">${foreign} invoice(s) in other currencies are excluded from dashboard totals. No foreign exchange conversion is applied.</p>`:''}<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Recent documents</h2><p>Your latest invoices and estimates</p></div><button class="link-button" data-page="invoices">View invoices ${ico('arrow')}</button></div><div class="table-wrap">${docs.length?`<table class="table"><thead><tr><th>Number</th><th>Customer</th><th>Amount</th><th>Status</th></tr></thead><tbody>${docs.map(d=>`<tr class="clickable" data-action="preview" data-id="${d.id}"><td><span class="strong">${E(d.number)}</span><span class="sub">${prettyDate(d.issued)}</span></td><td>${E(customer(d.customerId)?.name||'Unassigned')}</td><td class="money">${cMoney(totals(d).total,d)}</td><td>${badge(docStatus(d))}</td></tr>`).join('')}</tbody></table>`:empty('No documents yet','Create an invoice or estimate to get started.','Create invoice','new-invoice')}</div></section><aside><div class="overview-insight"><span>WORK SMARTER</span><h3>Every invoice starts with a conversation.</h3><p>Keep your clients, pricing and payment records in one straightforward workspace.</p><button data-action="new-invoice">Create your next invoice ${'→'}</button></div><section class="panel"><div class="panel-head"><div><h2>Quick actions</h2><p>Everything within a few taps</p></div></div><div class="panel-body quick-list">${[['new-invoice','invoice','New invoice','Bill a customer'],['new-estimate','estimate','Create an estimate','Send a price proposal'],['new-customer','users','Add a customer','Save contact details'],['new-item','box','Add a product or service','Build your price list']].map(([action,ic,title,subtitle])=>`<button class="quick-btn" data-action="${action}"><span class="quick-ico">${ico(ic)}</span><span><strong>${title}</strong><small>${subtitle}</small></span><span class="arrow">${ico('chevron')}</span></button>`).join('')}</div></section></aside></div>`}
function filterSearch(){return `<div class="search-bar"><label class="search-box">${ico('search')}<input id="table-search" type="search" autocomplete="off" placeholder="Search ${E(pageNames[ui.page].toLowerCase())}..." value="${E(ui.q)}" aria-label="Search" /></label>${['invoices','estimates'].includes(ui.page)?`<select id="table-filter" class="filter" aria-label="Filter status"><option value="all">All statuses</option>${(ui.page==='invoices'?['draft','sent','partial','paid','overdue']:['draft','sent','accepted','declined']).map(x=>`<option value="${x}" ${ui.filter===x?'selected':''}>${x==='partial'?'Part paid':x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select>`:''}</div>`}
function renderDocuments(kind){const isInv=kind==='invoice';let docs=state.documents.filter(d=>d.kind===kind);const query=ui.q.toLowerCase();docs=docs.filter(d=>(d.number+' '+(customer(d.customerId)?.name||'')).toLowerCase().includes(query)&&(ui.filter==='all'||docStatus(d)===ui.filter)).sort((a,b)=>b.issued.localeCompare(a.issued));return `${header(isInv?'Invoices':'Estimates',isInv?'Create, track and manage your customer invoices.':'Create quotes and turn accepted estimates into invoices.',`<button class="btn btn-primary" data-action="new-${kind}">${ico('plus')} New ${kind}</button>`)}${filterSearch()}<div class="panel"><div class="table-wrap">${docs.length?`<table class="table"><thead><tr><th>Number</th><th>Customer</th><th>Issued</th><th>${isInv?'Due date':'Valid until'}</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td class="strong"><a href="#" data-action="preview" data-id="${d.id}">${E(d.number)}</a></td><td>${E(customer(d.customerId)?.name||'Unassigned')}</td><td>${prettyDate(d.issued)}</td><td>${prettyDate(d.due)}</td><td class="money">${cMoney(totals(d).total,d)}</td><td>${badge(docStatus(d))}</td><td><div class="row-actions"><button class="icon-btn" title="View" aria-label="View ${E(d.number)}" data-action="preview" data-id="${d.id}">${ico('file')}</button><button class="icon-btn" title="Edit" aria-label="Edit ${E(d.number)}" data-action="edit-doc" data-id="${d.id}">${ico('edit')}</button></div></td></tr>`).join('')}</tbody></table>`:empty(`No ${isInv?'invoices':'estimates'} found`,ui.q||ui.filter!=='all'?'Try a different search or status.':`Create your first ${kind} in seconds.`,`Create ${kind}`,`new-${kind}`)}</div></div>`}
function renderCustomers(){let rows=state.customers.filter(c=>(c.name+' '+c.email+' '+c.phone).toLowerCase().includes(ui.q.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));return `${header('Customers','Keep every client organized, ready for your next invoice.',`<button class="btn btn-primary" data-action="new-customer">${ico('plus')} Add customer</button>`)}${filterSearch()}<div class="panel"><div class="table-wrap">${rows.length?`<table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Invoices</th><th>Billed</th><th></th></tr></thead><tbody>${rows.map(c=>{const docs=state.documents.filter(d=>d.kind==='invoice'&&d.status!=='draft'&&d.customerId===c.id&&docCurrency(d)===state.business.currency);return `<tr><td><div class="client-cell"><span class="pill-initial">${E(c.name.slice(0,2).toUpperCase())}</span><span class="strong">${E(c.name)}<span class="sub">${E(c.email)}</span></span></div></td><td>${E(c.phone||'—')}</td><td>${docs.length}</td><td class="money">${money(docs.reduce((a,d)=>a+totals(d).total,0))}</td><td><div class="row-actions"><button class="icon-btn" data-action="edit-customer" data-id="${c.id}" title="Edit customer">${ico('edit')}</button><button class="icon-btn" data-action="delete-customer" data-id="${c.id}" title="Delete customer">${ico('trash')}</button></div></td></tr>`}).join('')}</tbody></table>`:empty('No customers found','Save customer details once, use them on every invoice.','Add customer','new-customer','users')}</div></div>`}
function renderCatalog(){let rows=state.items.filter(x=>(x.name+' '+x.category+' '+x.description).toLowerCase().includes(ui.q.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));return `${header('Products & services','Your saved price list — ready to add to any document.',`<button class="btn btn-primary" data-action="new-item">${ico('plus')} Add item</button>`)}${filterSearch()}<div class="panel"><div class="table-wrap">${rows.length?`<table class="table"><thead><tr><th>Item</th><th>Type</th><th>Category</th><th>Unit price</th><th>Tax</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="strong">${E(x.name)}</span><span class="sub">${E(x.description)}</span></td><td>${E(x.type||'service')}</td><td>${E(x.category||'—')}</td><td class="money">${money(x.price)} <span class="muted tiny">/ ${E(x.unit||'item')}</span></td><td>${x.taxable?'Taxable':'Not taxed'}</td><td><div class="row-actions"><button class="icon-btn" data-action="edit-item" data-id="${x.id}" title="Edit item">${ico('edit')}</button><button class="icon-btn" data-action="delete-item" data-id="${x.id}" title="Delete item">${ico('trash')}</button></div></td></tr>`).join('')}</tbody></table>`:empty('No items found','Add your products or services here and reuse them in invoices and estimates.','Add item','new-item','box')}</div></div>`}
function renderExpenses(){let rows=state.expenses.filter(x=>(x.description+' '+x.vendor+' '+x.category).toLowerCase().includes(ui.q.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return `${header('Expenses','Keep a simple record of business costs.',`<button class="btn btn-primary" data-action="new-expense">${ico('plus')} Add expense</button>`)}<div class="metric-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="metric"><div class="metric-title">Total expenses<span class="metric-icon">${ico('wallet')}</span></div><div class="metric-value">${money(state.expenses.reduce((a,x)=>a+safeNumber(x.amount),0))}</div><div class="metric-foot">All recorded expenses</div></div><div class="metric"><div class="metric-title">This month<span class="metric-icon">${ico('clock')}</span></div><div class="metric-value">${money(state.expenses.filter(x=>monthKey(x.date)===monthKey(TODAY())).reduce((a,x)=>a+safeNumber(x.amount),0))}</div><div class="metric-foot">${new Date().toLocaleString('en-US',{month:'long',year:'numeric'})}</div></div></div>${filterSearch()}<div class="panel"><div class="table-wrap">${rows.length?`<table class="table"><thead><tr><th>Description</th><th>Vendor</th><th>Category</th><th>Date</th><th>Amount</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td class="strong">${E(x.description)}</td><td>${E(x.vendor||'—')}</td><td>${E(x.category||'Other')}</td><td>${prettyDate(x.date)}</td><td class="money">${money(x.amount)}</td><td><div class="row-actions"><button class="icon-btn" data-action="edit-expense" data-id="${x.id}" title="Edit expense">${ico('edit')}</button><button class="icon-btn" data-action="delete-expense" data-id="${x.id}" title="Delete expense">${ico('trash')}</button></div></td></tr>`).join('')}</tbody></table>`:empty('No expenses found','Record expenses to understand your costs.','Add expense','new-expense','wallet')}</div></div>`}
function renderReports(){const foreign=state.documents.filter(d=>d.kind==='invoice'&&d.status!=='draft'&&docCurrency(d)!==state.business.currency).length;const docs=state.documents.filter(d=>d.kind==='invoice'&&d.status!=='draft'&&docCurrency(d)===state.business.currency);const payments=docs.flatMap(d=>(d.payments||[]).map(p=>({...p,currency:d.currency||state.business.currency})));const cashIn=payments.reduce((a,p)=>a+safeNumber(p.amount),0);const expense=state.expenses.reduce((a,x)=>a+safeNumber(x.amount),0);const due=docs.reduce((a,d)=>a+totals(d).due,0);const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return {key:d.toISOString().slice(0,7),name:d.toLocaleString('en-US',{month:'short'})}});const chart=months.map(m=>({...m,value:payments.filter(p=>monthKey(p.date)===m.key).reduce((a,p)=>a+safeNumber(p.amount),0)}));const top=Math.max(1,...chart.map(x=>x.value));let customerAmounts=state.customers.map(c=>({name:c.name,amount:docs.filter(d=>d.customerId===c.id).reduce((a,d)=>a+totals(d).total,0)})).sort((a,b)=>b.amount-a.amount).filter(x=>x.amount>0).slice(0,5);return `${header('Reports','A clearer view of sales, payments and expenses.',`<button class="btn btn-secondary" data-action="csv">${ico('download')} Export CSV</button>`)}<div class="metric-grid">${[['Invoiced',docs.reduce((a,d)=>a+totals(d).total,0),'invoice'],['Payments recorded',cashIn,'credit'],['Outstanding',due,'clock'],['Expenses',expense,'wallet']].map(x=>`<div class="metric"><div class="metric-title">${x[0]}<span class="metric-icon">${ico(x[2])}</span></div><div class="metric-value">${money(x[1])}</div></div>`).join('')}</div><div class="report-grid"><section class="panel"><div class="panel-head"><div><h2>Payments by month</h2><p>Last six months · recorded payments</p></div><div class="chart-legend"><b></b> Received</div></div><div class="bar-chart">${chart.map(x=>`<div class="bar-col"><div class="bar-track"><div class="bar" title="${money(x.value)}" style="height:${Math.max(2,x.value/top*100)}%"></div></div><span>${x.name}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Top customers</h2><p>By invoiced amount</p></div></div>${customerAmounts.length?`<table class="table"><tbody>${customerAmounts.map((c,i)=>`<tr><td>${i+1}. &nbsp;${E(c.name)}</td><td class="money" style="text-align:right">${money(c.amount)}</td></tr>`).join('')}</tbody></table>`:empty('Nothing to report','Once you issue invoices, your top clients will appear here.')}</section></div><div class="help-row">${ico('info')} Reports are summaries only. They are not audited accounts or formal tax returns.</div>`}
function renderSettings(){const b=state.business;return `${header('Business settings','Make every invoice look like it came from your business.',`<button class="btn btn-primary" data-action="save-settings">${ico('check')} Save settings</button>`)}<div class="settings-grid"><section class="panel form-card"><h2 class="section-label">Business information</h2><div class="field-grid"><div class="field full"><label for="business-name">Business name</label><input id="business-name" data-setting="name" value="${E(b.name)}" maxlength="120" required></div><div class="field"><label>Email</label><input data-setting="email" type="email" value="${E(b.email)}" maxlength="160"></div><div class="field"><label>Phone</label><input data-setting="phone" value="${E(b.phone)}" maxlength="60"></div><div class="field full"><label>Business address</label><textarea data-setting="address" maxlength="500">${E(b.address)}</textarea></div><div class="field"><label>Tax identification number</label><input data-setting="taxId" value="${E(b.taxId)}" maxlength="90"></div><div class="field"><label>Website</label><input data-setting="website" value="${E(b.website)}" maxlength="180"></div><div class="field full"><label>Logo (optional)</label>${b.logo?`<img src="${E(b.logo)}" class="logo-preview" alt="Business logo" />`:''}<input id="logo-input" type="file" accept="image/png,image/jpeg,image/webp" /><span class="inline-note">PNG, JPG or WebP · under 350 KB for reliable backup</span>${b.logo?`<button class="btn btn-quiet btn-sm" data-action="remove-logo">Remove logo</button>`:''}</div></div></section><section class="panel form-card"><h2 class="section-label">Invoice preferences</h2><div class="field-grid"><div class="field"><label>Currency</label><select data-setting="currency">${['BSD','USD','CAD','GBP','EUR','JMD','BBD','TTD','XCD','GYD'].map(c=>`<option value="${c}" ${c===b.currency?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Tax label</label><input data-setting="taxLabel" value="${E(b.taxLabel)}" maxlength="25" placeholder="VAT / GST / Sales tax"></div><div class="field"><label>Default tax rate (%)</label><input data-setting="taxRate" type="number" min="0" max="100" step="0.01" value="${E(b.taxRate)}"></div><div class="field"><label>Invoice prefix</label><input data-setting="invoicePrefix" value="${E(b.invoicePrefix)}" maxlength="15"></div><div class="field"><label>Next invoice number</label><input data-setting="nextInvoice" type="number" min="1" step="1" value="${E(b.nextInvoice)}"></div><div class="field"><label>Estimate prefix</label><input data-setting="estimatePrefix" value="${E(b.estimatePrefix)}" maxlength="15"></div><div class="field"><label>Next estimate number</label><input data-setting="nextEstimate" type="number" min="1" step="1" value="${E(b.nextEstimate)}"></div><div class="field full"><label>Payment instructions</label><textarea data-setting="paymentInstructions" maxlength="1200">${E(b.paymentInstructions)}</textarea></div><div class="field full"><label>Default terms / thank-you note</label><textarea data-setting="terms" maxlength="1000">${E(b.terms)}</textarea></div></div><p class="tiny muted">Tax is 0% by default. Only charge tax where applicable and confirm the requirements for your business.</p></section><section class="panel form-card"><h2 class="section-label">Data & backups</h2><p class="tiny muted">Records are stored in this browser only. They do not sync across devices. Export backups regularly, especially before changing devices or clearing browser data.</p><div class="toolbar"><button class="btn btn-secondary" data-action="backup">${ico('download')} Download full backup</button><button class="btn btn-secondary" data-action="import">${ico('upload')} Restore backup</button><button class="btn btn-secondary" data-action="csv">${ico('download')} Export CSV</button></div><div class="data-warning" style="margin-top:18px">No automatic cloud backup or password protection. Anyone with access to this browser profile may access its records. Do not store card numbers or other payment credentials.</div></section><section class="panel form-card"><h2 class="section-label">Workspace</h2><p class="tiny muted">Start from an empty workspace when you're ready to use your real business information.</p><div class="toolbar"><button class="btn btn-danger" data-action="reset-data">${ico('trash')} Erase all local records</button></div><p class="tiny muted">This cannot be undone without a downloaded backup.</p></section></div>`}
function renderMore(){return `${header('More','Manage the rest of your workspace.') }<div class="panel" style="padding:15px">${navItems.slice(3).map(([id,ic,title])=>`<button class="quick-btn" data-page="${id}" style="margin:7px 0">${ico(ic)}<strong>${E(title)}</strong><span class="arrow">${ico('chevron')}</span></button>`).join('')}</div>`}
function renderPage(){return ({overview:renderOverview,invoices:()=>renderDocuments('invoice'),estimates:()=>renderDocuments('estimate'),customers:renderCustomers,catalog:renderCatalog,expenses:renderExpenses,reports:renderReports,settings:renderSettings,more:renderMore})[ui.page]?.()||renderOverview()}
const input=(label,name,value='',type='text',extras='')=>`<div class="field"><label for="f-${name}">${E(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${E(value)}" ${extras}></div>`;
const textarea=(label,name,value='',extras='')=>`<div class="field full"><label for="f-${name}">${E(label)}</label><textarea id="f-${name}" name="${name}" ${extras}>${E(value)}</textarea></div>`;
function modalFrame(title,subtitle,content,save='Save',wide=false,actions=''){return `<div class="modal-backdrop" data-action="close-backdrop"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="modal-header"><div><h2>${E(title)}</h2><small>${E(subtitle)}</small></div><button class="icon-btn" aria-label="Close" data-action="close-modal">${ico('close')}</button></div><div class="modal-content">${content}</div><div class="modal-footer"><span class="tiny muted">${wide?'Amounts are calculated automatically.':''}</span><div class="right"><button class="btn btn-secondary" data-action="close-modal">Cancel</button>${actions}<button class="btn btn-primary" data-action="save-modal">${ico('check')} ${E(save)}</button></div></div></div></div>`}
function openCustomer(id){ui.modal='customer';ui.draft=id?structuredClone(customer(id)):{id:uid(),name:'',email:'',phone:'',address:'',taxId:''};render()}
function openItem(id){ui.modal='item';ui.draft=id?structuredClone(state.items.find(x=>x.id===id)):{id:uid(),name:'',description:'',category:'General',type:'service',price:0,unit:'item',taxable:false};render()}
function openExpense(id){ui.modal='expense';ui.draft=id?structuredClone(state.expenses.find(x=>x.id===id)):{id:uid(),description:'',vendor:'',category:'Other',amount:0,date:TODAY(),notes:''};render()}
function newLine(){return {id:uid(),description:'',qty:1,price:0,unit:'item',taxable:state.business.taxRate>0}}
function openDoc(kind,id){const old=id?state.documents.find(x=>x.id===id):null;ui.modal='doc';ui.draft=old?structuredClone(old):{id:uid(),kind,number:'',customerId:'',issued:TODAY(),due:addDays(TODAY(),kind==='invoice'?14:30),currency:state.business.currency,lines:[newLine()],discount:0,taxRate:state.business.taxRate,notes:state.business.terms,status:'draft',payments:[]};render()}
function renderEntryModal(){const d=ui.draft;if(ui.modal==='customer')return modalFrame(d.name?'Edit customer':'Add customer','Saved customer details',`<form id="entry-form" class="field-grid">${input('Customer / company name','name',d.name,'text','required maxlength="140"')}${input('Email','email',d.email,'email','maxlength="200"')}${input('Phone','phone',d.phone,'tel','maxlength="70"')}${input('Tax identification number (optional)','taxId',d.taxId,'text','maxlength="90"')}${textarea('Billing address','address',d.address,'maxlength="500"')}</form>`,'Save customer');if(ui.modal==='item')return modalFrame(d.name?'Edit item':'Add item','Products and services can be reused in your invoices.',`<form id="entry-form" class="field-grid">${input('Name','name',d.name,'text','required maxlength="180"')}${input('Category','category',d.category,'text','maxlength="80"')}<div class="field"><label for="f-type">Type</label><select id="f-type" name="type"><option value="service" ${d.type==='service'?'selected':''}>Service</option><option value="product" ${d.type==='product'?'selected':''}>Product</option></select></div>${input('Unit','unit',d.unit,'text','maxlength="30"')}${input('Unit price','price',d.price,'number','min="0" step="0.01" required')}<div class="field"><label>Tax treatment</label><label style="display:flex;gap:8px;align-items:center;font-size:12px"><input type="checkbox" name="taxable" ${d.taxable?'checked':''}/> Taxable item</label></div>${textarea('Description (optional)','description',d.description,'maxlength="400"')}</form>`,'Save item');if(ui.modal==='expense')return modalFrame(d.description?'Edit expense':'Add expense','Track an expense for your business.',`<form id="entry-form" class="field-grid">${input('Description','description',d.description,'text','required maxlength="180"')}${input('Vendor','vendor',d.vendor,'text','maxlength="140"')}${input('Amount','amount',d.amount,'number','min="0" step="0.01" required')}${input('Date','date',d.date,'date','required')}${input('Category','category',d.category,'text','maxlength="90"')}${textarea('Notes','notes',d.notes,'maxlength="700"')}</form>`,'Save expense');return ''}
function docTotalsEditor(){const d=ui.draft;const t=totals(d);return `<div class="totals-box"><div class="totals-row"><span>Subtotal</span><strong>${cMoney(t.sub,d)}</strong></div><div class="totals-row"><label>Discount <input type="number" data-doc="discount" value="${E(d.discount)}" min="0" max="100" step="0.1" /> %</label><strong>− ${cMoney(t.disc,d)}</strong></div><div class="totals-row"><label>${E(state.business.taxLabel||'Tax')} <input type="number" data-doc="taxRate" min="0" max="100" step="0.01" value="${E(d.taxRate)}" /> %</label><strong>${cMoney(t.vat,d)}</strong></div><div class="totals-row grand"><span>Total</span><strong>${cMoney(t.total,d)}</strong></div></div>`}
function renderDocEditor(){const d=ui.draft;const isInv=d.kind==='invoice';const num=d.number||`Next: ${isInv?state.business.invoicePrefix:state.business.estimatePrefix}-${isInv?state.business.nextInvoice:state.business.nextEstimate}`;return modalFrame(d.number?`Edit ${d.kind}`:`New ${d.kind}`,num,`<div class="field-grid"><div class="field full"><label>Customer</label><select data-doc="customerId" id="doc-customer"><option value="">Select a customer</option>${state.customers.map(c=>`<option value="${E(c.id)}" ${d.customerId===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select>${!state.customers.length?'<span class="tiny muted">Add a customer first, then return to this document.</span>':''}</div><div class="field"><label>Issued on</label><input data-doc="issued" type="date" value="${E(d.issued)}"></div><div class="field"><label>${isInv?'Due date':'Valid until'}</label><input data-doc="due" type="date" value="${E(d.due)}"></div><div class="field"><label>Currency</label><select data-doc="currency">${['BSD','USD','CAD','GBP','EUR','JMD','BBD','TTD','XCD','GYD'].map(c=>`<option value="${c}" ${c===d.currency?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Status</label><select data-doc="status">${(isInv?['draft','sent']:['draft','sent','accepted','declined']).map(s=>`<option value="${s}" ${d.status===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div></div><div style="margin-top:24px" class="section-label">Line items</div><div class="field" style="max-width:400px"><label>Add from your saved catalog</label><select id="catalog-picker"><option value="">Choose a product or service…</option>${state.items.map(x=>`<option value="${E(x.id)}">${E(x.name)} · ${money(x.price)}</option>`).join('')}</select></div><div class="line-table"><table><thead><tr><th style="width:40%">Description</th><th>Qty</th><th>Rate</th><th>Unit</th><th>Tax</th><th></th></tr></thead><tbody>${d.lines.map(line=>`<tr><td><input data-line="${E(line.id)}" data-prop="description" value="${E(line.description)}" placeholder="Item or service" maxlength="220"></td><td><input class="narrow" data-line="${E(line.id)}" data-prop="qty" type="number" step="0.01" min="0.01" value="${E(line.qty)}"></td><td><input class="price" data-line="${E(line.id)}" data-prop="price" type="number" step="0.01" min="0" value="${E(line.price)}"></td><td><input style="width:84px" data-line="${E(line.id)}" data-prop="unit" value="${E(line.unit)}" maxlength="30"></td><td><input class="check" data-line="${E(line.id)}" data-prop="taxable" type="checkbox" ${line.taxable?'checked':''}></td><td><button class="delete-line" title="Remove line" data-action="delete-line" data-id="${E(line.id)}">${ico('trash',16)}</button></td></tr>`).join('')}</tbody></table></div><button class="btn btn-outline btn-sm" style="margin-top:11px" data-action="add-line">${ico('plus')} Add line</button><div id="live-totals">${docTotalsEditor()}</div><div class="field" style="margin-top:20px"><label>Notes / payment terms</label><textarea data-doc="notes" maxlength="1500">${E(d.notes)}</textarea></div>`,'Save document',true,`<button class="btn btn-secondary" data-action="save-and-preview">Save & preview</button>`)}
function previewHTML(d){const t=totals(d),c=customer(d.customerId)||{name:'Customer',address:'',email:'',phone:'',taxId:''},b=state.business;const title=d.kind==='estimate'?'ESTIMATE':(d.taxRate>0&&b.taxId?'VAT INVOICE':'INVOICE');return `<div class="doc-preview" id="document-to-print"><div class="preview-top"><div>${b.logo?`<img src="${E(b.logo)}" alt="Logo" style="max-height:70px;max-width:180px;object-fit:contain;margin-bottom:12px;display:block"/>`:''}<h2>${E(b.name)}</h2><div style="font-size:12px;line-height:1.7;color:#54656b;white-space:pre-line">${E(b.address)}${b.email?'\n'+E(b.email):''}${b.phone?'\n'+E(b.phone):''}${b.taxId?'\nTIN: '+E(b.taxId):''}</div></div><div class="preview-title"><h2>${title}</h2><p>${E(d.number)}</p>${badge(docStatus(d))}</div></div><div class="preview-middle"><div><small>Bill to</small><div style="font-weight:750;font-size:14px;margin-top:6px">${E(c.name)}</div><div style="white-space:pre-line">${E(c.address)}</div>${c.email?`<div>${E(c.email)}</div>`:''}${c.taxId?`<div>TIN: ${E(c.taxId)}</div>`:''}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;align-content:start"><div><small>Issue date</small><div>${prettyDate(d.issued)}</div></div><div><small>${d.kind==='invoice'?'Due date':'Valid until'}</small><div>${prettyDate(d.due)}</div></div><div><small>Currency</small><div>${E(docCurrency(d))}</div></div><div><small>Document no.</small><div>${E(d.number)}</div></div></div></div><div style="overflow-x:auto"><table class="preview-table"><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Taxable</th><th class="num">Amount</th></tr></thead><tbody>${(d.lines||[]).map(x=>`<tr><td><strong>${E(x.description)}</strong>${x.unit?`<br><span style="color:#9aadb0;font-size:10px">per ${E(x.unit)}</span>`:''}</td><td>${safeNumber(x.qty)}</td><td>${cMoney(x.price,d)}</td><td>${x.taxable?'Yes':'No'}</td><td class="num">${cMoney(round(x.qty*x.price),d)}</td></tr>`).join('')}</tbody></table></div><div class="preview-total"><div><span>Subtotal</span><strong>${cMoney(t.sub,d)}</strong></div>${d.discount>0?`<div><span>Discount (${safeNumber(d.discount)}%)</span><strong>− ${cMoney(t.disc,d)}</strong></div>`:''}<div><span>${E(b.taxLabel||'Tax')} (${safeNumber(d.taxRate)}%)</span><strong>${cMoney(t.vat,d)}</strong></div><div class="big"><span>Total</span><strong>${cMoney(t.total,d)}</strong></div>${d.kind==='invoice'&&t.paid>0?`<div><span>Payments received</span><strong>− ${cMoney(t.paid,d)}</strong></div><div style="font-size:15px;font-weight:780"><span>Balance due</span><strong>${cMoney(t.due,d)}</strong></div>`:''}</div>${d.notes||b.paymentInstructions?`<div class="preview-notes">${d.notes?`<strong>Notes & terms</strong>\n${E(d.notes)}\n\n`:''}${b.paymentInstructions?`<strong>How to pay</strong>\n${E(b.paymentInstructions)}`:''}</div>`:''}<div style="font-size:10px;color:#879599;margin-top:38px;border-top:1px solid #e9eeee;padding-top:12px">Thank you for your business.</div></div>`}
function renderPreview(){const d=state.documents.find(x=>x.id===ui.previewId);if(!d)return'';const t=totals(d);return `<div class="modal-backdrop" data-action="close-backdrop"><div class="modal wide" role="dialog" aria-modal="true" aria-label="Document preview"><div class="modal-header"><div><h2>${E(d.number)}</h2><small>${E(customer(d.customerId)?.name||'Unassigned')} · ${E(d.kind)} · ${docStatus(d)}</small></div><button class="icon-btn" data-action="close-modal" aria-label="Close">${ico('close')}</button></div><div class="modal-content"><div class="doc-print-wrap">${previewHTML(d)}</div><div class="toolbar" style="margin-top:15px">${d.kind==='invoice'?`<button class="btn btn-outline" data-action="add-payment" data-id="${d.id}" ${t.due<=0?'disabled':''}>${ico('credit')} Record payment</button>`:`<button class="btn btn-outline" data-action="convert-estimate" data-id="${d.id}">${ico('arrow')} Convert to invoice</button>`}<button class="btn btn-secondary" data-action="share-email" data-id="${d.id}">${ico('send')} Email text</button><button class="btn btn-secondary" data-action="share-wa" data-id="${d.id}">WhatsApp text</button>${d.kind==='invoice'&&d.payments?.length?`<span class="tiny muted">${d.payments.length} payment(s) recorded</span>`:''}</div><div class="help-row">${ico('info')} Message actions prepare text only; attach your saved PDF manually.</div></div><div class="modal-footer"><button class="btn btn-danger btn-sm" data-action="delete-doc" data-id="${d.id}">${ico('trash')} Delete</button><div class="right"><button class="btn btn-secondary" data-action="edit-doc" data-id="${d.id}">${ico('edit')} Edit</button><button class="btn btn-primary" data-action="print-doc" data-id="${d.id}">${ico('print')} Print / Save PDF</button></div></div></div></div>`}
function renderPayment(){const d=state.documents.find(x=>x.id===ui.previewId);if(!d)return'';return modalFrame('Record payment',`${E(d.number)} · Balance ${cMoney(totals(d).due,d)}`,`<form id="entry-form" class="field-grid">${input('Amount','amount',totals(d).due,'number',`min="0.01" max="${totals(d).due}" step="0.01" required`)}${input('Payment date','date',TODAY(),'date','required')}<div class="field"><label>Method</label><select name="method"><option>Cash</option><option>Bank transfer</option><option>Card</option><option>Other</option></select></div>${input('Reference (optional)','reference','','text','maxlength="120"')}</form>`,'Record payment')}
function renderModal(){if(!ui.modal)return'';if(ui.modal==='preview')return renderPreview();if(ui.modal==='payment')return renderPayment();if(ui.modal==='doc')return renderDocEditor();return renderEntryModal()}
function saveEntry(){const form=document.querySelector('#entry-form');if(!form||!form.reportValidity())return;const fd=new FormData(form);const d=ui.draft;if(ui.modal==='customer'){d.name=String(fd.get('name')||'').trim();d.email=String(fd.get('email')||'').trim();d.phone=String(fd.get('phone')||'').trim();d.taxId=String(fd.get('taxId')||'').trim();d.address=String(fd.get('address')||'').trim();if(!d.name)return alert('Customer name is required.');upsert('customers',d);}else if(ui.modal==='item'){d.name=String(fd.get('name')||'').trim();d.description=String(fd.get('description')||'').trim();d.category=String(fd.get('category')||'General').trim();d.type=String(fd.get('type')||'service');d.unit=String(fd.get('unit')||'item').trim();d.price=round(safeNumber(fd.get('price')));d.taxable=fd.has('taxable');if(!d.name)return alert('Item name is required.');upsert('items',d);}else if(ui.modal==='expense'){d.description=String(fd.get('description')||'').trim();d.vendor=String(fd.get('vendor')||'').trim();d.category=String(fd.get('category')||'Other').trim();d.amount=round(safeNumber(fd.get('amount')));d.date=String(fd.get('date')||TODAY());d.notes=String(fd.get('notes')||'').trim();if(!d.description||d.amount<=0)return alert('Enter a description and a positive amount.');upsert('expenses',d);}ui.modal=null;ui.draft=null;save();render();showToast('Saved successfully');}
function upsert(collection,record){const at=state[collection].findIndex(x=>x.id===record.id);if(at===-1)state[collection].push(record);else state[collection][at]=record}
function saveDocument(){const d=ui.draft;if(!d.customerId||!customer(d.customerId)){alert('Choose a customer before saving.');return false}if(!d.issued||!d.due){alert('Issue date and due date are required.');return false}if(!Array.isArray(d.lines)||!d.lines.length||d.lines.some(x=>!String(x.description||'').trim()||safeNumber(x.qty)<=0)){alert('Every line needs a description and a quantity above zero.');return false}if(d.kind==='invoice'&&d.payments?.length&&totals(d).paid>totals(d).total+.005){alert('Existing payments exceed the new total. Edit or remove payments before changing line amounts.');return false}if(!d.number){const b=state.business;const k=d.kind==='invoice'?'nextInvoice':'nextEstimate';const pre=d.kind==='invoice'?'invoicePrefix':'estimatePrefix';let candidate=`${b[pre]}-${b[k]}`;while(state.documents.some(x=>x.number===candidate)){b[k]++;candidate=`${b[pre]}-${b[k]}`}d.number=candidate;b[k]++}upsert('documents',d);save();return true}
function resetWorkspace(){const confirmed=confirm('Delete all saved invoices, customers, items, expenses and settings from this browser? You cannot undo this without a backup.');if(!confirmed)return;const again=prompt('Type DELETE to confirm erasing all local records:');if(again!=='DELETE')return;state=blank();save();navigate('settings');showToast('Empty workspace created')}
function printDocument(d){const popup=window.open('','_blank');if(!popup){alert('Allow pop-ups for this site to print or save a PDF.');return}const html=previewHTML(d).replace('class="doc-preview"','class="doc-preview print-document"');popup.document.open();popup.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${E(d.number)}</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#172a32;margin:0;padding:25px}h2{margin:0}.doc-preview{max-width:850px;margin:auto}.preview-top{display:flex;justify-content:space-between;gap:30px;border-bottom:2px solid #168b7b;padding-bottom:20px}.preview-title{text-align:right}.preview-title h2{font-size:26px;letter-spacing:1px}.preview-title p{color:#7e8a8a;font-size:12px}.badge{display:inline-block;background:#e5f4ef;color:#126c5d;border-radius:20px;padding:6px 10px;font-size:10px}.preview-middle{display:grid;grid-template-columns:1fr 1fr;gap:22px;padding:25px 0;font-size:12px;line-height:1.8}.preview-middle small{font-size:10px;text-transform:uppercase;letter-spacing:1.2px;color:#88999e;font-weight:bold}.preview-table{width:100%;border-collapse:collapse;margin:10px 0 18px}.preview-table th{background:#f0f8f4;padding:12px 9px;text-align:left;font-size:11px}.preview-table td{border-bottom:1px solid #e8eeee;padding:12px 9px;font-size:12px}.preview-table .num{text-align:right}.preview-total{width:270px;margin-left:auto;font-size:12px}.preview-total div{display:flex;justify-content:space-between;padding:8px 0}.preview-total .big{font-size:18px;font-weight:800;border-top:2px solid #168b7b;padding:15px 0}.preview-notes{white-space:pre-wrap;line-height:1.7;font-size:11px;color:#52666c;margin-top:25px;border-top:1px solid #e2ece8;padding-top:18px}@page{size:A4;margin:12mm}img{max-width:180px;max-height:70px}tr{break-inside:avoid}@media print{body{padding:0}button{display:none}}</style></head><body>${html}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));<\/script></body></html>`);popup.document.close();}
function contactShare(id,channel){const d=state.documents.find(x=>x.id===id);if(!d)return;const c=customer(d.customerId),t=totals(d);const message=`Hello ${c?.name||''},\n\nPlease find the details of ${d.kind} ${d.number} from ${state.business.name}.\nTotal: ${cMoney(t.total,d)}\n${d.kind==='invoice'?`Balance due: ${cMoney(t.due,d)}\nDue: ${prettyDate(d.due)}`:`Valid until: ${prettyDate(d.due)}`}\n\n${state.business.paymentInstructions||''}\n\nKind regards,\n${state.business.name}\n\nPlease see the attached PDF (attach it separately).`;if(channel==='email'){location.href=`mailto:${encodeURIComponent(c?.email||'')}?subject=${encodeURIComponent(`${state.business.name} — ${d.kind} ${d.number}`)}&body=${encodeURIComponent(message)}`}else{const phone=(c?.phone||'').replace(/[^\d]/g,'');window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer')}showToast('Message prepared — attach the PDF separately')}
function exportFile(name,content,type='application/octet-stream'){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1200)}
function backup(){exportFile(`invoice-studio-backup-${TODAY()}.json`,JSON.stringify(state,null,2),'application/json');showToast('Backup file downloaded')}
function csvCell(value){return `"${String(value??'').replace(/^[=+\-@\t\r]/,'\'$&').replace(/"/g,'""')}"`}
function csv(rows){return rows.map(row=>row.map(csvCell).join(',')).join('\r\n')}
function exportCSV(){const docRows=[['Kind','Number','Customer','Issue date','Due date','Status','Currency','Subtotal','Discount','Tax','Total','Paid','Outstanding'],...state.documents.map(d=>{const t=totals(d);return[d.kind,d.number,customer(d.customerId)?.name||'',d.issued,d.due,docStatus(d),docCurrency(d),t.sub,t.disc,t.vat,t.total,t.paid,t.due]})];const payments=[['Invoice','Date','Amount','Method','Reference'],...state.documents.flatMap(d=>(d.payments||[]).map(p=>[d.number,p.date,p.amount,p.method,p.reference]))];const expenses=[['Description','Vendor','Category','Date','Amount','Notes'],...state.expenses.map(x=>[x.description,x.vendor,x.category,x.date,x.amount,x.notes])];exportFile(`invoice-studio-documents-${TODAY()}.csv`,'\ufeff'+csv(docRows),'text/csv;charset=utf-8');exportFile(`invoice-studio-payments-${TODAY()}.csv`,'\ufeff'+csv(payments),'text/csv;charset=utf-8');exportFile(`invoice-studio-expenses-${TODAY()}.csv`,'\ufeff'+csv(expenses),'text/csv;charset=utf-8');showToast('Documents, payments and expenses exported')}
function validateBackup(v){if(!v||v.version!==1||typeof v.business!=='object'||!v.business||!['customers','items','documents','expenses'].every(k=>Array.isArray(v[k])))throw Error('Not a valid Invoice Studio backup.');if(v.documents.length>30000||v.customers.length>30000||v.items.length>30000||v.expenses.length>30000)throw Error('Backup has too many records.');for(const d of v.documents){if(!['invoice','estimate'].includes(d.kind)||!Array.isArray(d.lines)||d.lines.length>400||!Array.isArray(d.payments||[]))throw Error('Document records are invalid.')}if(v.business.logo&&!/^data:image\/(png|jpeg|webp);base64,/.test(v.business.logo))v.business.logo='';return v}
function importBackup(file){if(!file)return;if(file.size>8e6){alert('Backup exceeds the 8 MB import limit.');return}const reader=new FileReader();reader.onload=()=>{try{const incoming=validateBackup(JSON.parse(reader.result));if(!confirm('Restore this backup and replace all records currently saved on this browser? Download a backup first if needed.'))return;state=incoming;save();navigate('overview');showToast('Backup restored successfully')}catch(e){alert('Could not restore backup: '+e.message)}};reader.readAsText(file)}
function handleAction(action,id){if(action==='new-invoice')return openDoc('invoice');if(action==='new-estimate')return openDoc('estimate');if(action==='new-customer')return openCustomer();if(action==='new-item')return openItem();if(action==='new-expense')return openExpense();if(action==='edit-customer')return openCustomer(id);if(action==='edit-item')return openItem(id);if(action==='edit-expense')return openExpense(id);if(action==='edit-doc'){const d=state.documents.find(x=>x.id===id);if(d)return openDoc(d.kind,id)}if(action==='preview'){ui.previewId=id;ui.modal='preview';return render()}if(action==='close-modal'){ui.modal=null;ui.draft=null;return render()}if(action==='close-backdrop')return;if(action==='add-line'){ui.draft.lines.push(newLine());return render()}if(action==='delete-line'){if(ui.draft.lines.length<=1)return showToast('Keep at least one line item');ui.draft.lines=ui.draft.lines.filter(x=>x.id!==id);return render()}
 if(action==='save-modal'||action==='save-and-preview'){if(ui.modal==='doc'){const docId=ui.draft.id;if(!saveDocument())return;ui.modal=action==='save-and-preview'?'preview':null;ui.previewId=docId;ui.draft=null;render();showToast('Document saved')}else if(ui.modal==='payment'){const form=document.querySelector('#entry-form');if(!form.reportValidity())return;const fd=new FormData(form),d=state.documents.find(x=>x.id===ui.previewId),amount=round(Number(fd.get('amount')));if(!d||!Number.isFinite(amount)||amount<=0||amount>totals(d).due+.005){alert('Enter a valid amount no greater than the unpaid balance.');return}d.payments=d.payments||[];d.payments.push({id:uid(),amount,date:String(fd.get('date')||TODAY()),method:String(fd.get('method')||'Other'),reference:String(fd.get('reference')||'')});if(d.status==='draft')d.status='sent';save();ui.modal='preview';render();showToast('Payment recorded')}else saveEntry();return}
 if(action==='add-payment'){ui.previewId=id;ui.modal='payment';return render()}if(action==='print-doc'){const d=state.documents.find(x=>x.id===id);if(d)printDocument(d);return}if(action==='share-email'||action==='share-wa')return contactShare(id,action==='share-email'?'email':'wa');
 if(action==='convert-estimate'){const d=state.documents.find(x=>x.id===id);if(!d||d.kind!=='estimate')return;const b=state.business;let num=`${b.invoicePrefix}-${b.nextInvoice}`;while(state.documents.some(x=>x.number===num)){b.nextInvoice++;num=`${b.invoicePrefix}-${b.nextInvoice}`}b.nextInvoice++;const converted={...structuredClone(d),id:uid(),kind:'invoice',number:num,issued:TODAY(),due:addDays(TODAY(),14),status:'draft',payments:[]};d.status='accepted';state.documents.push(converted);save();return openDoc('invoice',converted.id)}
 if(action==='delete-doc'){if(!confirm('Delete this document permanently from this device?'))return;state.documents=state.documents.filter(x=>x.id!==id);save();ui.modal=null;render();showToast('Document deleted');return}if(action==='delete-customer'){if(state.documents.some(x=>x.customerId===id)){alert('This customer is used on a document. Keep their record or delete those documents first.');return}if(!confirm('Delete this customer?'))return;state.customers=state.customers.filter(x=>x.id!==id);save();render();return}if(action==='delete-item'||action==='delete-expense'){if(!confirm(`Delete this ${action==='delete-item'?'item':'expense'}?`))return;const c=action==='delete-item'?'items':'expenses';state[c]=state[c].filter(x=>x.id!==id);save();render();return}
 if(action==='save-settings'){if(!state.business.name.trim())return alert('Business name is required');state.business.taxRate=round(safeNumber(state.business.taxRate,0,100));state.business.nextInvoice=Math.max(1,Math.floor(Number(state.business.nextInvoice)||1001));state.business.nextEstimate=Math.max(1,Math.floor(Number(state.business.nextEstimate)||1001));save();render();showToast('Business settings saved');return}if(action==='remove-logo'){state.business.logo='';save();render();return}if(action==='backup')return backup();if(action==='csv')return exportCSV();if(action==='import')return document.getElementById('backup-import').click();if(action==='reset-data')return resetWorkspace();if(action==='clear-demo'){if(!confirm('Clear the demonstration data and start with your own business?'))return;state=blank();save();navigate('settings');showToast('Your workspace is ready');return}}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){e.preventDefault();navigate(page.dataset.page);return}const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='close-backdrop'&&e.target!==el)return;e.preventDefault();handleAction(el.dataset.action,el.dataset.id)});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='table-search'){const selection=el.selectionStart;ui.q=el.value;render();const next=document.getElementById('table-search');if(next){next.focus();try{next.setSelectionRange(selection,selection)}catch{}}return}if(el.matches('[data-setting]')){let value=el.value;if(['taxRate','nextInvoice','nextEstimate'].includes(el.dataset.setting))value=Number(value);state.business[el.dataset.setting]=value;return}if(el.matches('[data-doc]')&&ui.modal==='doc'){let value=el.type==='number'?Number(el.value):el.value;ui.draft[el.dataset.doc]=value;if(['discount','taxRate','currency'].includes(el.dataset.doc)){const parent=document.getElementById('live-totals');if(parent)parent.innerHTML=docTotalsEditor()}return}if(el.matches('[data-line]')&&ui.modal==='doc'){const line=ui.draft.lines.find(x=>x.id===el.dataset.line);if(!line)return;line[el.dataset.prop]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;const parent=document.getElementById('live-totals');if(parent)parent.innerHTML=docTotalsEditor();return}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='table-filter'){ui.filter=el.value;render();return}if(el.id==='catalog-picker'){const x=state.items.find(item=>item.id===el.value);if(!x)return;ui.draft.lines.push({id:uid(),description:x.name+(x.description?' — '+x.description:''),qty:1,price:x.price,unit:x.unit,taxable:!!x.taxable});render();return}if(el.id==='logo-input'){const file=el.files?.[0];if(!file)return;if(file.size>350000||!['image/png','image/jpeg','image/webp'].includes(file.type)){alert('Use PNG, JPG or WebP under 350 KB.');return}const reader=new FileReader();reader.onload=()=>{state.business.logo=reader.result;save();render();showToast('Logo saved')};reader.readAsDataURL(file);return}if(el.id==='backup-import'){importBackup(el.files?.[0]);el.value='';return}if(el.matches('[data-setting]')){state.business[el.dataset.setting]=el.type==='number'?Number(el.value):el.value;return}if(el.matches('[data-doc]')&&ui.modal==='doc'){ui.draft[el.dataset.doc]=el.type==='number'?Number(el.value):el.value;return}if(el.matches('[data-line]')&&ui.modal==='doc'){const line=ui.draft.lines.find(x=>x.id===el.dataset.line);if(line){line[el.dataset.prop]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;const parent=document.getElementById('live-totals');if(parent)parent.innerHTML=docTotalsEditor()}return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;ui.draft=null;render()}});
render();
if('serviceWorker'in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}